using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollmentRequests = [];

    public CatalogService()
    {
        _departments = CreateDepartments();
        _instructors = CreateInstructors();
        _courses = CreateCourses();
    }

    public IReadOnlyList<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.Find(d => d.Id == id);

    public IReadOnlyList<Course> GetCourses(string? search = null, int? departmentId = null, int? credits = null)
    {
        IEnumerable<Course> query = _courses;

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (credits.HasValue)
            query = query.Where(c => c.Credits == credits.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.OrderBy(c => c.Code).ToList();
    }

    public Course? GetCourse(int id) => _courses.Find(c => c.Id == id);

    public Instructor? GetInstructor(int id) => _instructors.Find(i => i.Id == id);

    public IReadOnlyList<Course> GetFeaturedCourses() =>
        _courses.Where(c => c.IsFeatured).ToList();

    public IReadOnlyList<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).OrderBy(c => c.Code).ToList();

    public IReadOnlyList<int> GetDistinctCredits() =>
        _courses.Select(c => c.Credits).Distinct().OrderBy(c => c).ToList();

    public void SubmitEnrollment(EnrollmentRequest request)
    {
        _enrollmentRequests.Add(request);
    }

    private static List<Department> CreateDepartments() =>
    [
        new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, quantity, structure, and space." },
        new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of English language, literature, and writing." },
        new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and human civilization." },
        new() { Id = 6, Name = "Biology", Code = "BIO", Description = "Study of living organisms and life processes." },
    ];

    private static List<Instructor> CreateInstructors() =>
    [
        new() { Id = 1, Name = "Dr. Alice Chen", Title = "Professor", Email = "achen@university.edu", Bio = "Dr. Chen specializes in artificial intelligence and machine learning. She has published over 50 papers in top-tier conferences and holds two patents in natural language processing.", OfficeLocation = "Science Building, Room 302" },
        new() { Id = 2, Name = "Dr. Robert Martinez", Title = "Associate Professor", Email = "rmartinez@university.edu", Bio = "Dr. Martinez focuses on software engineering and distributed systems. He spent 10 years in industry at major tech companies before joining academia.", OfficeLocation = "Science Building, Room 310" },
