using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollmentRequests = [];

    public CatalogService()
    {
        _departments = CreateDepartments();
        _instructors = CreateInstructors();
        _courses = CreateCourses();
    }

    public IReadOnlyList<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.Find(d => d.Id == id);

    public IReadOnlyList<Course> GetCourses(string? search = null, int? departmentId = null, int? credits = null)
    {
        IEnumerable<Course> query = _courses;

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (credits.HasValue)
            query = query.Where(c => c.Credits == credits.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.OrderBy(c => c.Code).ToList();
    }

    public Course? GetCourse(int id) => _courses.Find(c => c.Id == id);

    public Instructor? GetInstructor(int id) => _instructors.Find(i => i.Id == id);

    public IReadOnlyList<Course> GetFeaturedCourses() =>
        _courses.Where(c => c.IsFeatured).ToList();

    public IReadOnlyList<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).OrderBy(c => c.Code).ToList();

    public IReadOnlyList<int> GetDistinctCredits() =>
        _courses.Select(c => c.Credits).Distinct().OrderBy(c => c).ToList();

    public void SubmitEnrollment(EnrollmentRequest request)
    {
        _enrollmentRequests.Add(request);
    }

