        new() { Id = 3, Name = "Dr. Sarah Johnson", Title = "Professor", Email = "sjohnson@university.edu", Bio = "Dr. Johnson is a number theorist whose work bridges pure mathematics and cryptography. She is a recipient of the National Science Foundation CAREER Award.", OfficeLocation = "Mathematics Hall, Room 205" },
        new() { Id = 4, Name = "Dr. James Wilson", Title = "Assistant Professor", Email = "jwilson@university.edu", Bio = "Dr. Wilson researches quantum mechanics and condensed matter physics. He completed postdoctoral work at CERN.", OfficeLocation = "Physics Lab, Room 118" },
