        new() { Id = 6, Name = "Dr. Michael Brown", Title = "Associate Professor", Email = "mbrown@university.edu", Bio = "Dr. Brown is a historian of early modern Europe with a focus on the social and cultural history of the Renaissance.", OfficeLocation = "Humanities Building, Room 225" },
        new() { Id = 7, Name = "Dr. Lisa Park", Title = "Professor", Email = "lpark@university.edu", Bio = "Dr. Park is a molecular biologist studying gene regulation in eukaryotic cells. Her lab has made key discoveries in epigenetics.", OfficeLocation = "Life Sciences Building, Room 140" },
