{"file_text": "@page "/enroll"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService Catalog

<PageTitle>Enrollment Request — University Course Catalog</PageTitle>

<h1>Enrollment Request</h1>
<p>Fill out the form below to submit an enrollment request. You will receive a confirmation once your request has been processed.</p>

@if (submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for
            <strong>@(selectedCourse?.Code) — @(selectedCourse?.Title)</strong> has been received.</p>
        <hr />
        <p class="mb-0">You will be notified at <strong>@Model.Email</strong> once your request is reviewed.</p>
    </div>
    <a href="enroll" class="btn btn-primary">Submit Another Request</a>
    <a href="courses" class="btn btn-outline-secondary">Browse Courses</a>
}
else
{
    <EditForm method="post" Model="Model" OnValidSubmit="HandleSubmit" FormName="enrollment">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="row">
            <div class="col-md-6">
                <div class="mb-3">
                    <label for="studentName" class="form-label">Full Name <span class="text-danger">*</span></label>
                    <InputText id="studentName" @bind-Value="Model.StudentName" class="form-control" />
                    <ValidationMessage For="() => Model.StudentName" class="text-danger" />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID <span class="text-danger">*</span></label>
                    <InputText id="studentId" @bind-Value="Model.StudentId" class="form-control" placeholder="e.g., STU12345" />
                    <ValidationMessage For="() => Model.StudentId" class="text-danger" />
                </div>

                <div class="mb-3">
                    <label for="email" class="form-label">Email Address <span class="text-danger">*</span></label>
                    <InputText id="email" @bind-Value="Model.Email" class="form-control" placeholder="you@university.edu" />
                    <ValidationMessage For="() => Model.Email" class="text-danger" />
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course <span class="text-danger">*</span></label>
                    <InputSelect id="courseId" @bind-Value="Model.CourseId" class="form-select">
                        <option value="0">— Select a course —</option>
                        @foreach (var course in courses)
                        {
                            <option value="@course.Id">@course.Code — @course.Title (@course.Credits cr)</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => Model.CourseId" class="text-danger" />
                </div>

                <div class="mb-3">
                    <label for="comments" class="form-label">Comments (optional)</label>
                    <InputTextArea id="comments" @bind-Value="Model.Comments" class="form-control" rows="3" />
                    <ValidationMessage For="() => Model.Comments" class="text-danger" />
                </div>

                <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
                <a href="courses" class="btn btn-outline-secondary ms-2">Cancel</a>
            </div>
        </div>
    </EditForm>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private IReadOnlyList<Course> courses = [];
    private Course? selectedCourse;
    private bool submitted;

    protected override void OnInitialized()
    {
        courses = Catalog.GetCourses();

        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        selectedCourse = Catalog.GetCourse(Model.CourseId);
        Catalog.SubmitEnrollment(Model);
        submitted = true;
    }
}
", "path": "/tmp/sv-c0d1407fa2424d98b3c08ea8ad45c794/UniversityCourseCatalog/Components/Pages/Enroll.razor"}

