@if (selectedDepartment is not null)
{
    <div class="alert alert-info">
        Showing courses in <strong>@selectedDepartment.Name</strong>: @selectedDepartment.Description
    </div>
}

@if (courses.Count == 0)
{
    <div class="alert alert-warning">No courses match your search criteria.</div>
}
else
{
    <p class="text-muted">Showing @courses.Count course(s)</p>

    <table class="table table-striped table-hover">
